UPDATE "Invoices" i
SET "Status" = 'Paid',
    "PaidAt" = (s."PaidAt"::timestamp AT TIME ZONE 'America/Toronto'),
    "UpdatedAt" = now()
FROM spreadsheet s
WHERE i."InvoiceNumberId" = s."NumberId"
      AND left(i."InvoiceNumber", 2) = s."Prefix"
      AND s."Amount" IS NOT NULL AND abs(i."TotalNet" - s."Amount") < 0.05
  AND i."Status" = 'Pending'
  AND i."UpdatedAt" IS NULL;

