latest AS (
    SELECT DISTINCT ON (i."CompanyProfileId") i."CompanyProfileId", s."PaymentTermDays"
    FROM "Invoices" i
    JOIN spreadsheet s ON i."InvoiceNumberId" = s."NumberId"
      AND left(i."InvoiceNumber", 2) = s."Prefix"
      AND s."Amount" IS NOT NULL AND abs(i."TotalNet" - s."Amount") < 0.05
    ORDER BY i."CompanyProfileId", i."CreatedAt" DESC, i."NumberId" DESC
)
UPDATE "CompanyProfiles" cp
SET "PaymentTermDays" = latest."PaymentTermDays"
FROM latest
WHERE cp."Id" = latest."CompanyProfileId";
